import os,json,subprocess,stat,datetime
from pathlib import Path
src=Path("/opt/hopper")
dst=Path("/srv/projects/hopper")
root=Path("/srv/projects")
out={"phase":"hopper-root","utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"status":"BLOCKED","changed":False}
try:
 if not root.is_dir() or root.is_symlink() or not src.is_dir() or src.is_symlink() or dst.exists() or dst.is_symlink():
  raise RuntimeError("root_or_source_preflight_failed")
 before=src.stat()
 if before.st_dev!=root.stat().st_dev:raise RuntimeError("cross_filesystem_move_disallowed")
 if [x.name for x in src.iterdir() if x.name.startswith(".") and x.name!=".knownPackages"]:
  out["hidden_entries_present"]=True
 for p in Path("/proc").iterdir():
  if not p.name.isdecimal():continue
  for key in ("cwd","exe"):
   try:
    value=os.readlink(str(p/key))
    if value==str(src) or value.startswith(str(src)+"/"):raise RuntimeError("live_process_uses_source")
   except (FileNotFoundError,ProcessLookupError,PermissionError,OSError):continue
 moved=False
 try:
  os.rename(src,dst);moved=True
  os.symlink(str(dst),src)
  after=dst.stat()
  if not src.is_symlink() or src.resolve(strict=True)!=dst or not dst.is_dir() or dst.is_symlink() or after.st_ino!=before.st_ino or after.st_dev!=before.st_dev or after.st_uid!=before.st_uid or after.st_gid!=before.st_gid:
   raise RuntimeError("post_move_identity_check_failed")
  out.update(status="MOVED_AND_VERIFIED",changed=True,root=str(dst),legacy_alias=str(src),inode=after.st_ino,device=after.st_dev,ownership_preserved=True,entries=len(list(dst.iterdir())),rollback_needed=False)
 except Exception:
  if src.is_symlink() and src.resolve(strict=False)==dst:src.unlink()
  if moved and dst.is_dir() and not src.exists() and not src.is_symlink():os.rename(dst,src)
  raise
except Exception as e:out["error"]=str(e)[:180]
print(json.dumps(out,ensure_ascii=True,sort_keys=True))
if out["status"]!="MOVED_AND_VERIFIED":raise SystemExit(3)
